PRAGMA foreign_keys = ON;

-- R9: curated upper-primary story listening bank. Media remains on the original publisher/YouTube;
-- this table stores only catalogue metadata, curriculum grading and optional publisher companion links.
INSERT OR IGNORE INTO listening_sources (id,name,source_type,base_url,provider_ref,allowed_host,topic,default_level,usage_mode,enabled) VALUES
('listen-yt-british-council-kids','British Council LearnEnglish Kids','youtube_channel','https://www.youtube.com/@BritishCouncilLEKids','@BritishCouncilLEKids','youtube.com','Upper Primary Stories & English','P5','reference_only',1),
('listen-yt-oxford-owl','Oxford Owl – Learning at Home','youtube_channel','https://www.youtube.com/channel/UCllFxIfCNYQvsRepWxT7n8A','UCllFxIfCNYQvsRepWxT7n8A','youtube.com','Upper Primary Storytelling','P5','reference_only',1);

UPDATE listening_sources SET topic='Upper Primary Story Listening & English',updated_at=CURRENT_TIMESTAMP WHERE id='listen-yt-bbc';
UPDATE listening_sources SET topic='P6 Myths, Ideas & Critical Listening',updated_at=CURRENT_TIMESTAMP WHERE id='listen-yt-teded';

CREATE TABLE IF NOT EXISTS listening_story_catalog (
  id TEXT PRIMARY KEY,
  source_id TEXT NOT NULL REFERENCES listening_sources(id),
  title TEXT NOT NULL,
  youtube_search_title TEXT NOT NULL,
  reference_url TEXT NOT NULL,
  youtube_video_id TEXT,
  companion_url TEXT,
  companion_allowed_host TEXT,
  school_level TEXT NOT NULL CHECK(school_level IN ('P5','P6')),
  difficulty_band TEXT NOT NULL CHECK(difficulty_band IN ('foundation','standard','advanced')),
  difficulty_score REAL NOT NULL CHECK(difficulty_score>=1 AND difficulty_score<=10),
  topic TEXT NOT NULL,
  content_flags_json TEXT NOT NULL DEFAULT '[]',
  grading_reason TEXT NOT NULL,
  resolved_video_id TEXT,
  resolved_video_url TEXT,
  resolved_thumbnail_url TEXT,
  resolved_duration_seconds INTEGER,
  resolved_made_for_kids INTEGER,
  last_resolved_at TEXT,
  last_resolve_error TEXT,
  queue_count INTEGER NOT NULL DEFAULT 0,
  import_count INTEGER NOT NULL DEFAULT 0,
  last_queued_at TEXT,
  last_imported_at TEXT,
  enabled INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(source_id,title)
);
CREATE INDEX IF NOT EXISTS idx_listening_story_catalog_grade ON listening_story_catalog(enabled,school_level,difficulty_band,difficulty_score);
CREATE INDEX IF NOT EXISTS idx_listening_story_catalog_source ON listening_story_catalog(source_id,enabled);

